# ---- 落盘与校验 ----
assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
os.makedirs(BASE, exist_ok=True)
total = 0
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    e = P[cid]
    rec = {"case_id": cid, "prediction_text": e["prediction_text"], "basis": e["basis"],
           "confidence": e["confidence"], "trigger": e["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    total += os.path.getsize(path)
    for k in trig:
        if e["trigger"][k]:
            trig[k] += 1
# 逐件回读校验（只按本批id清单）
ok = 0
for cid in IDS:
    r = json.load(open(os.path.join(BASE, cid + ".json"), encoding="utf-8"))
    assert r["case_id"] == cid and r["prediction_text"] and r["basis"] and 0 <= r["confidence"] <= 1
    assert set(r["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    ok += 1
print(f"cases={len(IDS)} written={ok} total_bytes={total} trigger={trig}")
